import { test } from "node:test";
import assert from "node:assert/strict";
import { userHandlers, type User, type UserRepo } from "../src/users/handlers.ts";
import { makeRouter, type HttpRequest } from "../src/users/router.ts";

function setup() {
    const rows = new Map<string, User>();
    const repo: UserRepo & { listAll(): Promise<User[]> } = {
        get: async (id) => rows.get(id) ?? null,
        save: async (u) => void rows.set(u.id, u),
        listAll: async () => [...rows.values()],
    };
    const now = () => new Date("2026-11-19T12:00:00Z");
    const api = userHandlers(repo, now);
    const route = makeRouter(repo, now);
    const req = (id: string, body: unknown, headers: Record<string, string> = {}) => ({ params: { id }, headers, body });
    const http = (method: string, path: string, body?: unknown, extra: Partial<HttpRequest> = {}): Promise<{ status: number; headers?: Record<string, string>; body?: unknown }> =>
        route({ method, path, query: {}, headers: { "Content-Type": "application/json" }, rawBody: body === undefined ? "" : JSON.stringify(body), ...extra });
    return { api, rows, req, http };
}

const ada = { name: "Ada Lovelace", email: "ada@example.com", plan: "free" };

test("PUT creates a user with 201 and a Location header", async () => {
    const { api, req } = setup();
    const res = await api.put(req("u1", ada));
    assert.equal(res.status, 201);
    assert.equal(res.headers?.Location, "/users/u1");
    assert.equal(res.headers?.ETag, '"1"');
});

test("PATCH changes only the fields that are sent", async () => {
    const { api, req } = setup();
    await api.put(req("u1", ada));
    const res = await api.patch(req("u1", { plan: "pro" }));
    console.log("after PATCH { plan: 'pro' }:", res.body);
    assert.equal(res.status, 200);
    assert.deepEqual(res.body, { ...ada, plan: "pro", id: "u1", version: 2, updatedAt: "2026-11-19T12:00:00.000Z" });
});

test("PATCH with an empty body changes nothing but the version", async () => {
    const { api, rows, req } = setup();
    await api.put(req("u1", ada));
    await api.patch(req("u1", {}));
    assert.equal(rows.get("u1")?.email, "ada@example.com");
    assert.equal(rows.get("u1")?.version, 2);
});

test("PATCH validates input and checks the user exists", async () => {
    const { api, req } = setup();
    assert.equal((await api.patch(req("nobody", { plan: "pro" }))).status, 404);
    await api.put(req("u1", ada));
    assert.equal((await api.patch(req("u1", { nickname: "ada" }))).status, 400);
    assert.equal((await api.patch(req("u1", { plan: "enterprise" }))).status, 400);
});

test("a stale If-Match is rejected with 412 and nothing changes", async () => {
    const { api, rows, req } = setup();
    await api.put(req("u1", ada));
    await api.patch(req("u1", { name: "Ada K." }, { "if-match": '"1"' }));
    const stale = await api.patch(req("u1", { plan: "team" }, { "if-match": '"1"' }));
    assert.equal(stale.status, 412);
    assert.equal(rows.get("u1")?.plan, "free");
    assert.equal(rows.get("u1")?.name, "Ada K.");
});

test("the router answers unsupported methods, bad bodies and unknown paths before any handler runs", async () => {
    const { http } = setup();
    const del = await http("DELETE", "/users/u1");
    assert.equal(del.status, 405);
    assert.equal(del.headers?.Allow, "GET, PUT, PATCH");
    assert.equal((await http("POST", "/users", ada)).headers?.Allow, "GET");
    assert.equal((await http("PUT", "/users/u1", undefined, { rawBody: "{name:" })).status, 400);
    assert.equal((await http("PUT", "/users/u1", ada, { headers: { "Content-Type": "text/plain" } })).status, 415);
    assert.equal((await http("GET", "/users/a/b")).status, 404);
    assert.equal((await http("OPTIONS", "/users/u1")).headers?.Allow, "GET, PUT, PATCH, OPTIONS");
});

test("upgrading a plan through the HTTP API keeps the user's name and email", async () => {
    const { http } = setup();
    assert.equal((await http("PUT", "/users/u7", ada)).status, 201);
    const patched = await http("PATCH", "/users/u7", { plan: "team" }, { headers: { "content-type": "application/json", "If-Match": '"1"' } });
    assert.equal(patched.status, 200);
    const got = (await http("GET", "/users/u7")).body as User;
    assert.deepEqual([got.name, got.email, got.plan, got.version], ["Ada Lovelace", "ada@example.com", "team", 2]);
    // a client holding version 2 revalidates without downloading it again
    const cached = await http("GET", "/users/u7", undefined, { headers: { "If-None-Match": '"2"' } });
    assert.deepEqual([cached.status, cached.body], [304, undefined]);
});

test("GET /users pages by id with a Link to the next page, and filters by plan", async () => {
    const { http } = setup();
    for (let i = 1; i <= 5; i++) await http("PUT", `/users/u${i}`, { ...ada, name: `User ${i}`, plan: i % 2 ? "pro" : "free" });
    const first = await http("GET", "/users", undefined, { query: { limit: "2" } });
    assert.deepEqual((first.body as { items: { id: string }[] }).items.map((u) => u.id), ["u1", "u2"]);
    assert.equal(first.headers?.Link, '</users?limit=2&after=u2>; rel="next"');
    const last = await http("GET", "/users", undefined, { query: { limit: "2", after: "u4" } });
    assert.deepEqual((last.body as { items: { id: string }[] }).items.map((u) => u.id), ["u5"]);
    assert.equal(last.headers?.Link, undefined);
    const pro = await http("GET", "/users", undefined, { query: { plan: "pro" } });
    assert.deepEqual((pro.body as { items: { id: string; plan: string }[] }).items.map((u) => u.id), ["u1", "u3", "u5"]);
    assert.equal(pro.headers?.["X-Total-Count"], "3");
    const named = await http("GET", "/users", undefined, { query: { q: "USER 4" } });
    assert.deepEqual((named.body as { items: { id: string }[] }).items.map((u) => u.id), ["u4"]);
    assert.equal((await http("GET", "/users", undefined, { query: { limit: "500" } })).status, 400);
});
